"""Offline policy variant. **Not model output** — generated by ScriptedVariantDeveloper.

This is a template: ``{{MODE}}`` is substituted with one of the modes in
``VARIANT_MODES`` before the file is written. Each mode is a genuinely different
exploration strategy, so the variants land on different points of the
``(n, a)`` plane and earn genuinely different ``V``. They exist so the replay,
Eq(1) and selection machinery can be exercised with no model in the loop.

Contract
--------
``select(observation, rho) -> list[str]``, returning a subset of
``observation.legal_actions`` with no duplicates and at most
``observation.max_parallelism`` entries. ``[]`` stops the episode. Deterministic:
the same observation and rho always yield the same list, in a stable order, so
the replay digest is reproducible.

Modes
-----
``score_first``   exploit: highest observed score first, root rarely revisited.
``breadth_first`` explore: shallowest first, root is expanded every round.
``depth_first``   chain: deepest first, root only when nothing else is legal.
"""
from __future__ import annotations

from typing import Any

#: Substituted at generation time; the four modes are mutually exclusive.
_MODE = "{{MODE}}"

_ROOT_TRIGGER = {
    "score_first": 0.75,
    "breadth_first": 0.0,
    "depth_first": 1.01,  # effectively "only when nothing else is legal"
}


def _rank(node: Any, mode: str) -> tuple[float, ...]:
    """Ranking key for one node; larger is picked first."""
    score = float(node.score)
    depth = int(node.depth)
    index = int(node.creation_index)
    if mode == "breadth_first":
        return (-float(depth), score, float(index))
    if mode == "depth_first":
        return (float(depth), score, float(index))
    return (score, -float(depth), float(index))


def select(observation: Any, rho: float) -> list[str]:
    legal = list(observation.legal_actions)
    if not legal:
        return []

    workers = max(1, int(observation.max_parallelism))
    rho_clamped = max(0.0, min(1.0, float(rho)))
    by_id = {node.node_id: node for node in observation.nodes}
    root_id = observation.node_ids[0] if observation.node_ids else None

    # The budget knob sets how many parents this round expands. Every mode
    # obeys it identically, so the rho sweep measures the ranking rule and not
    # a difference in budget appetite.
    width = 1 + round(rho_clamped * (workers - 1))
    width = max(1, min(width, workers, len(legal)))

    candidates = [nid for nid in legal if nid != root_id and nid in by_id]
    candidates.sort(key=lambda nid: (_rank(by_id[nid], _MODE), nid), reverse=True)
    chosen = candidates[:width]

    wants_root = (
        root_id is not None
        and root_id in legal
        and (rho_clamped >= _ROOT_TRIGGER[_MODE] or not chosen)
    )
    if wants_root and root_id not in chosen:
        if len(chosen) >= width:
            chosen = chosen[: width - 1]
        chosen.append(root_id)

    chosen.sort(key=lambda nid: int(by_id[nid].creation_index) if nid in by_id else -1)
    return chosen
